import{_ as t,o as e,c as s,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"全栈集成组装配方与能力自检","description":"按结果形态拼装协议、Nuxt 主线与可选 React/AI SDK，给出配方 A–D、决策表与跨组自检清单。","frontmatter":{"title":"全栈集成组装配方与能力自检","description":"按结果形态拼装协议、Nuxt 主线与可选 React/AI SDK，给出配方 A–D、决策表与跨组自检清单。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/integration/assembly/assembly-recipes-checklist.md","filePath":"ts-ai/integration/assembly/assembly-recipes-checklist.md","lastUpdated":1786113687000}'),i={name:"ts-ai/integration/assembly/assembly-recipes-checklist.md"};function r(l,a,d,o,p,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="全栈集成组装配方与能力自检" tabindex="-1">全栈集成组装配方与能力自检 <a class="header-anchor" href="#全栈集成组装配方与能力自检" aria-label="Permalink to &quot;全栈集成组装配方与能力自检&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>协议、交互设计、Nuxt（及可选 React）各组偏专题。本篇不重抄组件百科，只回答：<strong>要组装成哪种前端结果、抄哪条配方、进 quality 前还缺什么。</strong></p><p>服务端组装见 <a href="/ts-ai/backend/assembly/assembly-recipes-checklist">AI 服务组装配方</a>；知识侧见 <a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 与记忆组装配方</a>。本篇站在 <strong>全栈集成 / 前端交付</strong> 视角。</p><h2 id="_1-你要组装的结果形态" tabindex="-1">1. 你要组装的结果形态 <a class="header-anchor" href="#_1-你要组装的结果形态" aria-label="Permalink to &quot;1. 你要组装的结果形态&quot;">​</a></h2><h3 id="_1-1-只读流式聊天" tabindex="-1">1.1 只读流式聊天 <a class="header-anchor" href="#_1-1-只读流式聊天" aria-label="Permalink to &quot;1.1 只读流式聊天&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入</span></span>
<span class="line"><span>  → POST Run</span></span>
<span class="line"><span>  → SSE：run.started → message.delta* → message.completed → run.completed</span></span>
<span class="line"><span>  → 气泡展示（可含 citation.added）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>无工具确认、无上传。入口：<a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a>。</p><h3 id="_1-2-聊天-工具确认" tabindex="-1">1.2 聊天 + 工具确认 <a class="header-anchor" href="#_1-2-聊天-工具确认" aria-label="Permalink to &quot;1.2 聊天 + 工具确认&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>… → tool.confirmation_required</span></span>
<span class="line"><span>  → UI 批准/拒绝 REST</span></span>
<span class="line"><span>  → tool.started → tool.completed → message.* → run.completed|cancelled</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>原则：<a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认与人在回路</a>；实现：<a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a>。</p><h3 id="_1-3-聊天-文件索引状态" tabindex="-1">1.3 聊天 + 文件索引状态 <a class="header-anchor" href="#_1-3-聊天-文件索引状态" aria-label="Permalink to &quot;1.3 聊天 + 文件索引状态&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>multipart 上传 → pending → indexing → ready|failed（file.index.updated）</span></span>
<span class="line"><span>  → 仅 ready 的 fileIds 进入 Run</span></span>
<span class="line"><span>  → 流式回答（可 citation.added）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>实现：<a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">文件上传与索引状态</a>；服务端：<a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a>。</p><h2 id="_2-能力拼装图" tabindex="-1">2. 能力拼装图 <a class="header-anchor" href="#_2-能力拼装图" aria-label="Permalink to &quot;2. 能力拼装图&quot;">​</a></h2><h3 id="_2-1-协议与传输必备件" tabindex="-1">2.1 协议与传输必备件 <a class="header-anchor" href="#_2-1-协议与传输必备件" aria-label="Permalink to &quot;2.1 协议与传输必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>事件全表与增量语义</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">Message、Run 与 Tool Call 事件</a></td></tr><tr><td>REST / SSE / WS 选型</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP、SSE 与 WebSocket</a></td></tr><tr><td>分帧解析</td><td><a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流式事件解析</a></td></tr><tr><td>取消、重连、去重</td><td><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与去重</a></td></tr><tr><td>鉴权 / 文件 / 错误码</td><td><a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权、文件与错误协议</a></td></tr></tbody></table><h3 id="_2-2-前端状态与渲染必备件" tabindex="-1">2.2 前端状态与渲染必备件 <a class="header-anchor" href="#_2-2-前端状态与渲染必备件" aria-label="Permalink to &quot;2.2 前端状态与渲染必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>流式反馈原则</td><td><a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态与反馈</a></td></tr><tr><td>Chat 信息架构</td><td><a href="/ts-ai/integration/ai-interaction/chat-information-architecture">Chat 信息架构</a></td></tr><tr><td>Nuxt 目录边界</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">Nuxt AI 项目结构</a></td></tr><tr><td>send / stream / cancel</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Agent Chat Composable</a></td></tr><tr><td>messages / run 规范化</td><td><a href="/ts-ai/integration/vue-nuxt/message-run-state-management">消息与 Run 状态管理</a></td></tr><tr><td>增量渲染与滚动</td><td><a href="/ts-ai/integration/vue-nuxt/streaming-message-rendering">流式消息渲染</a></td></tr><tr><td>代理与鉴权</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">Nuxt 对接 NestJS</a></td></tr><tr><td>SSR 边界</td><td><a href="/ts-ai/integration/vue-nuxt/ssr-hydration-client-state">SSR、Hydration 与客户端状态</a></td></tr></tbody></table><h3 id="_2-3-与-nest-rag-workflow-的接缝" tabindex="-1">2.3 与 Nest / RAG / Workflow 的接缝 <a class="header-anchor" href="#_2-3-与-nest-rag-workflow-的接缝" aria-label="Permalink to &quot;2.3 与 Nest / RAG / Workflow 的接缝&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  → Nuxt proxy（Token）</span></span>
<span class="line"><span>  → Nest：Run / SSE /（可选）decision / files</span></span>
<span class="line"><span>  → Agent / 队列 /（可选）Interrupt</span></span>
<span class="line"><span>  →（可选）Ingestion Worker → 向量库</span></span>
<span class="line"><span>  → 产品事件回前端</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><table tabindex="0"><thead><tr><th>接缝</th><th>别在前端做</th></tr></thead><tbody><tr><td>Abort Run</td><td>只发取消；执行中断在 backend</td></tr><tr><td>Embedding</td><td>只展示 <code>file.index.*</code></td></tr><tr><td>图内 resume</td><td>确认 API；机制在 workflow</td></tr></tbody></table><h2 id="_3-推荐配方" tabindex="-1">3. 推荐配方 <a class="header-anchor" href="#_3-推荐配方" aria-label="Permalink to &quot;3. 推荐配方&quot;">​</a></h2><h3 id="_3-1-配方-a-假事件流最小-chat" tabindex="-1">3.1 配方 A：假事件流最小 Chat <a class="header-anchor" href="#_3-1-配方-a-假事件流最小-chat" aria-label="Permalink to &quot;3.1 配方 A：假事件流最小 Chat&quot;">​</a></h3><p><strong>何时用：</strong> 第一天验证 UI；无 Nest、无真模型。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Composer → 本地 script 喂 ProductSseEvent</span></span>
<span class="line"><span>  → applyMessageDelta / run.completed</span></span>
<span class="line"><span>  → MessageList</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>抄：<a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a>。上线前必须换成配方 B。</p><h3 id="_3-2-配方-b-nuxt-nest-sse-真链路" tabindex="-1">3.2 配方 B：Nuxt + Nest SSE 真链路 <a class="header-anchor" href="#_3-2-配方-b-nuxt-nest-sse-真链路" aria-label="Permalink to &quot;3.2 配方 B：Nuxt + Nest SSE 真链路&quot;">​</a></h3><p><strong>何时用：</strong> 主线交付；工单助手要真回答。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>useAgentChat.send</span></span>
<span class="line"><span>  → POST /v1/threads/:id/runs</span></span>
<span class="line"><span>  → GET  /v1/runs/:id/stream</span></span>
<span class="line"><span>  → parser → reducer → UI</span></span>
<span class="line"><span>  → cancel → Abort + POST cancel</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Agent Chat Composable</a> + <a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">Nuxt 对接 NestJS</a> + <a href="/ts-ai/integration/vue-nuxt/complete-ai-chat-project">AI Chat 拼装验收清单</a>。服务端 SSE：<a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a>。</p><h3 id="_3-3-配方-c-工具确认-取消重连" tabindex="-1">3.3 配方 C：工具确认 + 取消重连 <a class="header-anchor" href="#_3-3-配方-c-工具确认-取消重连" aria-label="Permalink to &quot;3.3 配方 C：工具确认 + 取消重连&quot;">​</a></h3><p><strong>何时用：</strong> 有写操作工具（退款、改址）；要 HITL。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配方 B</span></span>
<span class="line"><span>  + tool.* 卡片与 decision API</span></span>
<span class="line"><span>  + Last-Event-ID / 游标重连</span></span>
<span class="line"><span>  + 确认中禁用发送或串行 Run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>拼：<a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a> + <a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消、重连与去重</a>。需要上传时再叠 §1.3。</p><h3 id="_3-4-配方-d-ai-sdk-适配-可选" tabindex="-1">3.4 配方 D：AI SDK 适配（可选） <a class="header-anchor" href="#_3-4-配方-d-ai-sdk-适配-可选" aria-label="Permalink to &quot;3.4 配方 D：AI SDK 适配（可选）&quot;">​</a></h3><p><strong>何时用：</strong> 团队强制 AI SDK；自建协议已通。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nest 仍发 ProductSseEvent</span></span>
<span class="line"><span>  → 薄映射层 → @ai-sdk/vue 渲染（或仅纯文本子页）</span></span>
<span class="line"><span>  → HITL / file.index 仍走自建面板</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>必读：<a href="/ts-ai/integration/vue-nuxt/ai-sdk-vue-integration">AI SDK Vue 集成</a>。<strong>禁止</strong>用 SDK 替换事件契约。React 侧扩展见 <a href="/ts-ai/integration/react-next/vercel-ai-sdk">Vercel AI SDK</a>。</p><h2 id="_4-决策表" tabindex="-1">4. 决策表 <a class="header-anchor" href="#_4-决策表" aria-label="Permalink to &quot;4. 决策表&quot;">​</a></h2><h3 id="_4-1-自建协议-vs-ai-sdk" tabindex="-1">4.1 自建协议 vs AI SDK <a class="header-anchor" href="#_4-1-自建协议-vs-ai-sdk" aria-label="Permalink to &quot;4.1 自建协议 vs AI SDK&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>默认工单助手、要 HITL/文件索引</td><td><strong>自建协议</strong></td></tr><tr><td>已通自建且老板要 SDK UI</td><td><strong>薄适配（配方 D）</strong></td></tr><tr><td>后端改成只吐 SDK 流</td><td><strong>不推荐</strong></td></tr></tbody></table><h3 id="_4-2-sse-vs-websocket" tabindex="-1">4.2 SSE vs WebSocket <a class="header-anchor" href="#_4-2-sse-vs-websocket" aria-label="Permalink to &quot;4.2 SSE vs WebSocket&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>单向 Run 流式</td><td><strong>SSE</strong>（主线）</td></tr><tr><td>双向高频、多人同 Thread</td><td>WebSocket（<a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">协议选型</a>）</td></tr><tr><td>仅短问答</td><td>同步 REST 也可</td></tr></tbody></table><h3 id="_4-3-nuxt-主线-vs-react-扩展" tabindex="-1">4.3 Nuxt 主线 vs React 扩展 <a class="header-anchor" href="#_4-3-nuxt-主线-vs-react-扩展" aria-label="Permalink to &quot;4.3 Nuxt 主线 vs React 扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>本手册默认前端</td><td><strong>Nuxt</strong></td></tr><tr><td>团队全员 React / 已有 Next</td><td><a href="/ts-ai/integration/react-next/">React 与 Next.js 扩展</a>；事件契约不变</td></tr><tr><td>两边都要</td><td>共享 <code>ProductSseEvent</code> 类型包；UI 分端实现</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只会假数据？ → 配方 A</span></span>
<span class="line"><span>要真客服？ → 配方 B</span></span>
<span class="line"><span>有退款类工具？ → 配方 C</span></span>
<span class="line"><span>被要求 AI SDK？ → 配方 D（叠在 B/C 上）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_5-能力自检清单" tabindex="-1">5. 能力自检清单 <a class="header-anchor" href="#_5-能力自检清单" aria-label="Permalink to &quot;5. 能力自检清单&quot;">​</a></h2><p>进入 <a href="/ts-ai/quality/">质量与生产</a> 或对外演示前勾选。</p><h3 id="_5-1-协议自检" tabindex="-1">5.1 协议自检 <a class="header-anchor" href="#_5-1-协议自检" aria-label="Permalink to &quot;5.1 协议自检&quot;">​</a></h3><ul><li>[ ] 前后端共用同一 <code>ProductSseEvent</code> 联合类型</li><li>[ ] <code>message.delta</code> 为增量 append；有 <code>message.completed</code> 策略</li><li>[ ] 未知 <code>type</code> 忽略且不打断流</li><li>[ ] 取消可 abort；重连有游标 / 去重</li><li>[ ] 错误码与鉴权失败可映射到 UI</li></ul><h3 id="_5-2-nuxt-主线自检" tabindex="-1">5.2 Nuxt 主线自检 <a class="header-anchor" href="#_5-2-nuxt-主线自检" aria-label="Permalink to &quot;5.2 Nuxt 主线自检&quot;">​</a></h3><ul><li>[ ] 假事件与真 Nest 两条路径都能终态</li><li>[ ] composable 在 unmount / 切 Thread 时清理</li><li>[ ] 代理下 SSE 不被缓冲截断</li><li>[ ] Chat 岛无 hydration mismatch（流式不在 SSR 假造半句）</li><li>[ ] <a href="/ts-ai/integration/vue-nuxt/complete-ai-chat-project">AI Chat 拼装验收清单</a> §7.1 全绿</li></ul><h3 id="_5-3-体验与无障碍自检" tabindex="-1">5.3 体验与无障碍自检 <a class="header-anchor" href="#_5-3-体验与无障碍自检" aria-label="Permalink to &quot;5.3 体验与无障碍自检&quot;">​</a></h3><ul><li>[ ] running / 确认中状态可感知（不只靠颜色）</li><li>[ ] 引用可打开或可复制来源（若启用 <code>citation.added</code>）</li><li>[ ] 工具确认展示真实参数</li><li>[ ] 键盘可发送、取消、批准/拒绝</li><li>[ ] 移动端输入区可用（<a href="/ts-ai/integration/ai-interaction/accessibility-mobile">无障碍与移动端</a>）</li></ul><h3 id="_5-4-react-扩展自检-若启用" tabindex="-1">5.4 React 扩展自检（若启用） <a class="header-anchor" href="#_5-4-react-扩展自检-若启用" aria-label="Permalink to &quot;5.4 React 扩展自检（若启用）&quot;">​</a></h3><ul><li>[ ] 明确标注为扩展，非主线前置</li><li>[ ] Hook 与 Vue composable 事件名一致</li><li>[ ] 未另造一套 Run 生命周期</li><li>[ ] 选型记录见 <a href="/ts-ai/integration/react-next/nuxt-nextjs-selection">Nuxt 与 Next.js 选型</a></li></ul><h2 id="_6-未通过时的回跳路径" tabindex="-1">6. 未通过时的回跳路径 <a class="header-anchor" href="#_6-未通过时的回跳路径" aria-label="Permalink to &quot;6. 未通过时的回跳路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缺口</th><th>回跳</th></tr></thead><tbody><tr><td>事件名 / 顺序混乱</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">Message、Run 与 Tool Call 事件</a></td></tr><tr><td>传不起来 / 选错通道</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP、SSE 与 WebSocket</a></td></tr><tr><td>状态机与反馈原则</td><td><a href="/ts-ai/integration/ai-interaction/">AI 交互设计</a></td></tr><tr><td>Nuxt 主线不会拼</td><td><a href="/ts-ai/integration/vue-nuxt/">Vue 3 与 Nuxt</a> → <a href="/ts-ai/integration/vue-nuxt/complete-ai-chat-project">AI Chat 拼装验收清单</a></td></tr><tr><td>工具确认</td><td><a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a></td></tr><tr><td>上传索引</td><td><a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">文件上传与索引状态</a></td></tr><tr><td>AI SDK 犹豫</td><td><a href="/ts-ai/integration/vue-nuxt/ai-sdk-vue-integration">AI SDK Vue 集成</a></td></tr><tr><td>Nest Run/SSE 本身挂</td><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">服务端组装配方</a></td></tr><tr><td>检索 / 引用无依据</td><td><a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a></td></tr></tbody></table><h2 id="_7-验收标准" tabindex="-1">7. 验收标准 <a class="header-anchor" href="#_7-验收标准" aria-label="Permalink to &quot;7. 验收标准&quot;">​</a></h2><p>能不看目录，根据场景在配方 A–D 中选型；能画出协议 ↔ Nuxt ↔ Nest 接缝；能用 §5 指出协议 / Nuxt / 体验 /（可选）React 中未完成项。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地假流     → 配方 A</span></span>
<span class="line"><span>真客服主线   → 配方 B</span></span>
<span class="line"><span>HITL 工具    → 配方 C</span></span>
<span class="line"><span>强制 AI SDK  → 配方 D（不删契约）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,62)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
